// La lógica de verificación de la función `compras` de Senda, con respuestas de Google INVENTADAS.
// En Senda la huella de la cuenta es un SHA-256; acá es una función simple para que corra en cualquier navegador.
// En Senda, esas respuestas llegan de la API Android Publisher (subscriptionsv2.get).
const VIGENTES = ["SUBSCRIPTION_STATE_ACTIVE", "SUBSCRIPTION_STATE_IN_GRACE_PERIOD", "SUBSCRIPTION_STATE_CANCELED"];

const huella = async (usuario) => "huella:" + usuario;

// Devuelve la fecha hasta la que vale la suscripción, o un motivo de rechazo.
async function verificar(datos, producto, usuario, ahora) {
  const linea = (datos.lineItems ?? []).find((l) => l.productId === producto);
  if (!linea?.expiryTime) return "rechazo: no hay ese producto en la compra";
  if (!VIGENTES.includes(datos.subscriptionState)) return "rechazo: estado " + datos.subscriptionState.replace("SUBSCRIPTION_STATE_", "");
  if (new Date(linea.expiryTime) <= ahora) return "rechazo: ya venció";
  if (datos.externalAccountIdentifiers?.obfuscatedExternalAccountId !== (await huella(usuario))) return "rechazo: la compra es de otra cuenta";
  return "ok, vale hasta " + linea.expiryTime;
}

const ahora = new Date("2026-12-20T12:00:00Z");
const ana = "cuenta-de-ana";
const google = async (estado, producto, vence, dueno) => ({
  subscriptionState: estado,
  lineItems: [{ productId: producto, expiryTime: vence }],
  externalAccountIdentifiers: { obfuscatedExternalAccountId: await huella(dueno) },
});

const casos = [
  ["activa, de Ana", await google("SUBSCRIPTION_STATE_ACTIVE", "senda_max_mensual", "2027-01-15T00:00:00Z", ana), "senda_max_mensual"],
  ["en período de gracia", await google("SUBSCRIPTION_STATE_IN_GRACE_PERIOD", "senda_max_mensual", "2026-12-22T00:00:00Z", ana), "senda_max_mensual"],
  ["cancelada, sigue vigente", await google("SUBSCRIPTION_STATE_CANCELED", "senda_max_mensual", "2026-12-28T00:00:00Z", ana), "senda_max_mensual"],
  ["en espera (on hold)", await google("SUBSCRIPTION_STATE_ON_HOLD", "senda_max_mensual", "2026-12-10T00:00:00Z", ana), "senda_max_mensual"],
  ["Premium presentada como Max", await google("SUBSCRIPTION_STATE_ACTIVE", "senda_premium_mensual", "2027-01-15T00:00:00Z", ana), "senda_max_mensual"],
  ["compra de otra cuenta", await google("SUBSCRIPTION_STATE_ACTIVE", "senda_max_mensual", "2027-01-15T00:00:00Z", "cuenta-de-beto"), "senda_max_mensual"],
];
for (const [nombre, datos, pedido] of casos) {
  console.log(nombre.padEnd(30), "->", await verificar(datos, pedido, ana, ahora));
}

// Cuánto queda de una suscripción de USD 10, sin impuestos, según la tarifa de cada tienda.
// Las tarifas son las de la documentación oficial al 16-11-2026. Los USD 10 son inventados.
const precio = 10;
const escenarios = [
  { n: "Google Play, mercado fuera de EEE/UK/EE. UU./Australia/Japón", tarifa: 0.15, cobro: 0 },
  { n: "Google Play, EEE/UK/EE. UU. (esquema nuevo, desde 30-06-2026)", tarifa: 0.10, cobro: 0.05 },
  { n: "Apple, primer año de una persona suscripta", tarifa: 0.30, cobro: 0 },
  { n: "Apple, después de un año de servicio pago", tarifa: 0.15, cobro: 0 },
  { n: "Apple, Programa de Pequeños Negocios", tarifa: 0.15, cobro: 0 },
];
for (const e of escenarios) {
  const tienda = precio * (e.tarifa + e.cobro);
  console.log(e.n.padEnd(66), "tienda USD", tienda.toFixed(2), "| te queda USD", (precio - tienda).toFixed(2));
}
